[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>WellSource — Expert health guidance you can trust</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
    <style>
        *, *::before, *::after {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        :root {
            --brand-primary: oklch(55% 0.14 185);
            --brand-primary-light: oklch(65% 0.12 185);
            --brand-primary-dark: oklch(45% 0.14 185);
            --text-primary: oklch(20% 0.02 0);
            --text-secondary: oklch(45% 0.02 0);
            --text-muted: oklch(60% 0.02 0);
            --bg-primary: oklch(99% 0.005 0);
            --bg-secondary: oklch(97% 0.008 0);
            --bg-card: oklch(100% 0 0);
            --accent-coral: oklch(70% 0.16 35);
            --accent-coral-hover: oklch(65% 0.18 35);
            --border-light: oklch(90% 0.01 0);
            --shadow-subtle: 0 2px 8px oklch(0% 0 0 / 0.08);
            --shadow-elevated: 0 8px 32px oklch(0% 0 0 / 0.12);
            --radius-sm: 8px;
            --radius-md: 12px;
            --radius-lg: 24px;
            --transition: 200ms ease-out;
        }

        html {
            scroll-behavior: smooth;
        }

        body {
            font-family: 'Inter', system-ui, -apple-system, sans-serif;
            background-color: var(--bg-primary);
            color: var(--text-primary);
            line-height: 1.625;
            -webkit-font-smoothing: antialiased;
        }

        a {
            text-decoration: none;
            color: inherit;
        }

        img {
            max-width: 100%;
            display: block;
        }

        button {
            font-family: inherit;
            cursor: pointer;
            border: none;
            background: none;
        }

        .container {
            max-width: 1280px;
            margin: 0 auto;
            padding: 0 24px;
        }

        @media (min-width: 768px) {
            .container {
                padding: 0 48px;
            }
        }

        /* Header Navigation */
        .header {
            background: var(--bg-card);
            border-bottom: 1px solid var(--border-light);
            position: sticky;
            top: 0;
            z-index: 1000;
        }

        .header-inner {
            display: flex;
            align-items: center;
            justify-content: space-between;
            height: 72px;
        }

        .logo {
            font-size: 28px;
            font-weight: 700;
            color: var(--brand-primary);
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .logo svg {
            width: 36px;
            height: 36px;
        }

        .nav {
            display: none;
        }

        @media (min-width: 1024px) {
            .nav {
                display: flex;
                gap: 8px;
            }
        }

        .nav-item {
            position: relative;
        }

        .nav-link {
            display: flex;
            align-items: center;
            gap: 4px;
            padding: 8px 16px;
            font-weight: 500;
            font-size: 15px;
            color: var(--text-primary);
            border-radius: var(--radius-sm);
            transition: background var(--transition), color var(--transition);
        }

        .nav-link:hover {
            background: var(--bg-secondary);
            color: var(--brand-primary);
        }

        .nav-link svg {
            width: 16px;
            height: 16px;
            transition: transform var(--transition);
        }

        .nav-item:hover .nav-link svg {
            transform: rotate(180deg);
        }

        .nav-dropdown {
            position: absolute;
            top: 100%;
            left: 50%;
            transform: translateX(-50%) translateY(10px);
            background: var(--bg-card);
            border-radius: var(--radius-md);
            box-shadow: var(--shadow-elevated);
            border: 1px solid var(--border-light);
            padding: 24px;
            min-width: 600px;
            opacity: 0;
            visibility: hidden;
            transition: opacity var(--transition), transform var(--transition), visibility var(--transition);
        }

        .nav-item:hover .nav-dropdown {
            opacity: 1;
            visibility: visible;
            transform: translateX(-50%) translateY(0);
        }

        .dropdown-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 24px;
        }

        .dropdown-column h4 {
            font-size: 12px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            color: var(--text-muted);
            margin-bottom: 12px;
        }

        .dropdown-column ul {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: 8px;
        }

        .dropdown-column a {
            font-size: 14px;
            color: var(--text-secondary);
            transition: color var(--transition);
        }

        .dropdown-column a:hover {
            color: var(--brand-primary);
        }

        .header-actions {
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .btn-subscribe {
            background: var(--brand-primary);
            color: white;
            padding: 10px 20px;
            border-radius: var(--radius-md);
            font-weight: 600;
            font-size: 14px;
            transition: background var(--transition);
        }

        .btn-subscribe:hover {
            background: var(--brand-primary-dark);
        }

        .btn-signin {
            font-weight: 500;
            font-size: 14px;
            color: var(--text-secondary);
            transition: color var(--transition);
        }

        .btn-signin:hover {
            color: var(--brand-primary);
        }

        @media (min-width: 1024px) {
            .btn-signin {
                display: none;
            }
        }

        .mobile-menu-btn {
            display: flex;
            flex-direction: column;
            gap: 5px;
            padding: 8px;
        }

        @media (min-width: 1024px) {
            .mobile-menu-btn {
                display: none;
            }
        }

        .mobile-menu-btn span {
            width: 24px;
            height: 2px;
            background: var(--text-primary);
            border-radius: 2px;
        }

        /* Credibility Ticker */
        .ticker-bar {
            background: var(--brand-primary);
            padding: 14px 0;
            overflow: hidden;
        }

        .ticker-track {
            display: flex;
            animation: ticker 30s linear infinite;
        }

        .ticker-bar:hover .ticker-track {
            animation-play-state: paused;
        }

        @keyframes ticker {
            0% { transform: translateX(0); }
            100% { transform: translateX(-50%); }
        }

        .ticker-content {
            display: flex;
            align-items: center;
            gap: 48px;
            padding-right: 48px;
        }

        .ticker-item {
            display: flex;
            align-items: center;
            gap: 12px;
            color: white;
            font-weight: 600;
            font-size: 14px;
            white-space: nowrap;
        }

        .ticker-item .stat {
            font-size: 18px;
            font-weight: 700;
        }

        .ticker-item .label {
            opacity: 0.9;
        }

        .ticker-divider {
            width: 6px;
            height: 6px;
            background: var(--accent-coral);
            transform: rotate(45deg);
            flex-shrink: 0;
        }

        /* Hero Section */
        .hero {
            padding: 48px 0;
        }

        .hero-grid {
            display: grid;
            grid-template-columns: 1fr;
            gap: 32px;
        }

        @media (min-width: 1024px) {
            .hero-grid {
                grid-template-columns: 2fr 1fr;
            }
        }

        .hero-featured {
            position: relative;
            border-radius: var(--radius-lg);
            overflow: hidden;
            background: linear-gradient(135deg, var(--brand-primary) 0%, var(--brand-primary-dark) 100%);
            min-height: 400px;
            display: flex;
            flex-direction: column;
            justify-content: flex-end;
            padding: 32px;
        }

        .hero-badge {
            position: absolute;
            top: 24px;
            left: 24px;
            background: rgba(255, 255, 255, 0.95);
            color: var(--brand-primary);
            padding: 8px 16px;
            border-radius: 100px;
            font-size: 12px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.05em;
        }

        .hero-challenge {
            position: absolute;
            top: 24px;
            right: 24px;
            background: var(--accent-coral);
            color: white;
            padding: 8px 16px;
            border-radius: 100px;
            font-size: 12px;
            font-weight: 600;
            display: flex;
            align-items: center;
            gap: 6px;
        }

        .hero-content {
            color: white;
            z-index: 1;
        }

        .hero-category {
            font-size: 13px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.08em;
            opacity: 0.85;
            margin-bottom: 12px;
        }

        .hero-title {
            font-size: 28px;
            font-weight: 700;
            line-height: 1.2;
            margin-bottom: 16px;
        }

        @media (min-width: 768px) {
            .hero-title {
                font-size: 36px;
            }
        }

        .hero-subtitle {
            font-size: 16px;
            line-height: 1.6;
            opacity: 0.9;
            max-width: 540px;
        }

        /* Trending Sidebar */
        .trending {
            background: var(--bg-card);
            border-radius: var(--radius-lg);
            padding: 28px;
            box-shadow: var(--shadow-subtle);
        }

        .trending-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 24px;
        }

        .trending-title {
            font-size: 18px;
            font-weight: 700;
        }

        .trending-list {
            display: flex;
            flex-direction: column;
            gap: 20px;
        }

        .trending-item {
            display: flex;
            gap: 16px;
        }

        .trending-item a {
            display: flex;
            gap: 16px;
            width: 100%;
        }

        .trending-number {
            font-size: 24px;
            font-weight: 700;
            color: var(--brand-primary);
            opacity: 0.3;
            line-height: 1;
            min-width: 28px;
        }

        .trending-info {
            flex: 1;
        }

        .trending-category {
            display: inline-block;
            font-size: 11px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            color: var(--brand-primary);
            margin-bottom: 6px;
        }

        .trending-headline {
            font-size: 15px;
            font-weight: 600;
            line-height: 1.4;
            color: var(--text-primary);
            transition: color var(--transition);
        }

        .trending-item:hover .trending-headline {
            color: var(--brand-primary);
        }

        /* Newsletter CTA */
        .newsletter-cta {
            background: var(--accent-coral);
            padding: 64px 0;
            margin: 80px 0;
        }

        .newsletter-inner {
            display: flex;
            flex-direction: column;
            align-items: center;
            text-align: center;
            gap: 24px;
        }

        .newsletter-heading {
            font-size: 32px;
            font-weight: 700;
            color: white;
        }

        @media (min-width: 768px) {
            .newsletter-heading {
                font-size: 40px;
            }
        }

        .newsletter-body {
            font-size: 18px;
            color: rgba(255, 255, 255, 0.9);
            max-width: 540px;
        }

        .newsletter-form {
            display: flex;
            flex-direction: column;
            gap: 12px;
            width: 100%;
            max-width: 460px;
        }

        @media (min-width: 540px) {
            .newsletter-form {
                flex-direction: row;
            }
        }

        .newsletter-input {
            flex: 1;
            padding: 16px 20px;
            border: none;
            border-radius: var(--radius-md);
            font-size: 16px;
            font-family: inherit;
        }

        .newsletter-input::placeholder {
            color: var(--text-muted);
        }

        .newsletter-btn {
            background: var(--text-primary);
            color: white;
            padding: 16px 32px;
            border-radius: var(--radius-md);
            font-weight: 600;
            font-size: 16px;
            white-space: nowrap;
            transition: background var(--transition);
        }

        .newsletter-btn:hover {
            background: var(--brand-primary);
        }

        .newsletter-privacy {
            font-size: 13px;
            color: rgba(255, 255, 255, 0.75);
        }

        /* Section Header */
        .section-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 32px;
        }

        .section-title {
            font-size: 28px;
            font-weight: 700;
        }

        .section-link {
            font-weight: 600;
            color: var(--brand-primary);
            display: flex;
            align-items: center;
            gap: 6px;
            transition: gap var(--transition);
        }

        .section-link:hover {
            gap: 10px;
        }

        /* Health Topics Carousel */
        .health-topics {
            padding: 80px 0;
            background: var(--bg-secondary);
            margin: 0 -24px;
            padding-left: 24px;
            padding-right: 24px;
        }

        @media (min-width: 768px) {
            .health-topics {
                margin: 0 -48px;
                padding-left: 48px;
                padding-right: 48px;
            }
        }

        .topics-carousel-wrapper {
            position: relative;
        }

        .topics-carousel {
            display: flex;
            gap: 24px;
            overflow-x: auto;
            scroll-snap-type: x mandatory;
            scrollbar-width: none;
            -ms-overflow-style: none;
            padding-bottom: 16px;
        }

        .topics-carousel::-webkit-scrollbar {
            display: none;
        }

        .topic-card {
            flex: 0 0 auto;
            scroll-snap-align: start;
            text-align: center;
            width: 140px;
        }

        .topic-image {
            width: 140px;
            height: 140px;
            border-radius: 50%;
            background: var(--bg-card);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 48px;
            margin-bottom: 16px;
            box-shadow: var(--shadow-subtle);
            overflow: hidden;
            transition: transform var(--transition), box-shadow var(--transition);
        }

        .topic-card:hover .topic-image {
            transform: scale(1.05);
            box-shadow: var(--shadow-elevated);
        }

        .topic-image img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        .topic-label {
            font-size: 15px;
            font-weight: 600;
            color: var(--text-primary);
        }

        .carousel-nav {
            display: none;
            position: absolute;
            top: 50%;
            transform: translateY(-50%);
            width: 44px;
            height: 44px;
            border-radius: 50%;
            background: var(--bg-card);
            box-shadow: var(--shadow-subtle);
            align-items: center;
            justify-content: center;
            z-index: 10;
            transition: background var(--transition);
        }

        .carousel-nav:hover {
            background: var(--brand-primary);
            color: white;
        }

        .carousel-nav svg {
            width: 20px;
            height: 20px;
        }

        .carousel-prev {
            left: -22px;
        }

        .carousel-next {
            right: -22px;
        }

        @media (min-width: 768px) {
            .carousel-nav {
                display: flex;
            }
        }

        /* Health Tools */
        .health-tools {
            padding: 80px 0;
        }

        .tools-grid {
            display: grid;
            grid-template-columns: 1fr;
            gap: 32px;
        }

        @media (min-width: 768px) {
            .tools-grid {
                grid-template-columns: 2fr 1fr;
            }
        }

        .tools-main {
            background: var(--bg-secondary);
            border-radius: var(--radius-lg);
            padding: 32px;
        }

        .tools-main-header {
            margin-bottom: 24px;
        }

        .tools-main-title {
            font-size: 24px;
            font-weight: 700;
            margin-bottom: 8px;
        }

        .tools-main-desc {
            font-size: 15px;
            color: var(--text-secondary);
            line-height: 1.6;
        }

        .tools-list {
            display: grid;
            grid-template-columns: 1fr;
            gap: 16px;
        }

        @media (min-width: 540px) {
            .tools-list {
                grid-template-columns: repeat(2, 1fr);
            }
        }

        .tool-card {
            background: var(--bg-card);
            border-radius: var(--radius-sm);
            padding: 20px;
            display: flex;
            flex-direction: column;
            gap: 8px;
            transition: box-shadow var(--transition), transform var(--transition);
        }

        .tool-card:hover {
            box-shadow: var(--shadow-subtle);
            transform: translateY(-2px);
        }

        .tool-card h4 {
            font-size: 16px;
            font-weight: 600;
        }

        .tool-card p {
            font-size: 13px;
            color: var(--text-secondary);
            line-height: 1.5;
        }

        .tools-sidebar {
            display: flex;
            flex-direction: column;
            gap: 16px;
        }

        .tool-sidebar-card {
            background: var(--bg-card);
            border-radius: var(--radius-sm);
            padding: 20px;
            box-shadow: var(--shadow-subtle);
            flex: 1;
        }

        .tool-sidebar-card h4 {
            font-size: 16px;
            font-weight: 600;
            margin-bottom: 8px;
        }

        .tool-sidebar-card p {
            font-size: 13px;
            color: var(--text-secondary);
            line-height: 1.5;
            margin-bottom: 12px;
        }

        .tool-sidebar-btn {
            display: inline-block;
            padding: 8px 16px;
            background: var(--brand-primary);
            color: white;
            border-radius: var(--radius-sm);
            font-size: 13px;
            font-weight: 600;
            transition: background var(--transition);
        }

        .tool-sidebar-btn:hover {
            background: var(--brand-primary-dark);
        }

        /* Recommended Reads */
        .recommended-reads {
            padding: 80px 0;
            background: var(--bg-secondary);
        }

        .tabs {
            display: flex;
            gap: 4px;
            overflow-x: auto;
            scrollbar-width: none;
            -ms-overflow-style: none;
            margin-bottom: 32px;
            border-bottom: 2px solid var(--border-light);
        }

        .tabs::-webkit-scrollbar {
            display: none;
        }

        .tab {
            padding: 12px 20px;
            font-size: 15px;
            font-weight: 600;
            color: var(--text-secondary);
            border-radius: var(--radius-sm) var(--radius-sm) 0 0;
            transition: color var(--transition), background var(--transition);
            white-space: nowrap;
        }

        .tab:hover {
            color: var(--brand-primary);
            background: rgba(2, 131, 141, 0.05);
        }

        .tab.active {
            color: var(--brand-primary);
            background: transparent;
            position: relative;
        }

        .tab.active::after {
            content: '';
            position: absolute;
            bottom: -2px;
            left: 0;
            right: 0;
            height: 2px;
            background: var(--brand-primary);
        }

        .articles-grid {
            display: grid;
            grid-template-columns: 1fr;
            gap: 24px;
        }

        @media (min-width: 640px) {
            .articles-grid {
                grid-template-columns: repeat(2, 1fr);
            }
        }

        @media (min-width: 1024px) {
            .articles-grid {
                grid-template-columns: repeat(3, 1fr);
            }
        }

        .article-card {
            background: var(--bg-card);
            border-radius: var(--radius-sm);
            overflow: hidden;
            box-shadow: var(--shadow-subtle);
            transition: box-shadow var(--transition), transform var(--transition);
        }

        .article-card:hover {
            box-shadow: var(--shadow-elevated);
            transform: translateY(-4px);
        }

        .article-image {
            aspect-ratio: 16 / 10;
            background: var(--bg-secondary);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 48px;
        }

        .article-image img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        .article-content {
            padding: 20px;
        }

        .article-category {
            display: inline-block;
            font-size: 11px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            color: var(--brand-primary);
            margin-bottom: 8px;
        }

        .article-title {
            font-size: 17px;
            font-weight: 600;
            line-height: 1.4;
            margin-bottom: 8px;
            transition: color var(--transition);
        }

        .article-card:hover .article-title {
            color: var(--brand-primary);
        }

        .article-meta {
            font-size: 13px;
            color: var(--text-muted);
        }

        /* Trust Section */
        .trust-section {
            padding: 80px 0;
        }

        .trust-header {
            text-align: center;
            margin-bottom: 48px;
        }

        .trust-title {
            font-size: 32px;
            font-weight: 700;
            margin-bottom: 16px;
        }

        .trust-grid {
            display: grid;
            grid-template-columns: 1fr;
            gap: 24px;
        }

        @media (min-width: 640px) {
            .trust-grid {
                grid-template-columns: repeat(2, 1fr);
            }
        }

        @media (min-width: 1024px) {
            .trust-grid {
                grid-template-columns: repeat(4, 1fr);
            }
        }

        .trust-pillar {
            text-align: center;
            padding: 32px 24px;
        }

        .trust-icon {
            width: 64px;
            height: 64px;
            border-radius: 50%;
            background: rgba(2, 131, 141, 0.1);
            display: flex;
            align-items: center;
            justify-content: center;
            margin: 0 auto 20px;
            color: var(--brand-primary);
        }

        .trust-icon svg {
            width: 28px;
            height: 28px;
        }

        .trust-pillar h3 {
            font-size: 18px;
            font-weight: 700;
            margin-bottom: 10px;
        }

        .trust-pillar p {
            font-size: 14px;
            color: var(--text-secondary);
            line-height: 1.6;
        }

        /* Featured Programs */
        .featured-programs {
            padding: 80px 0;
            background: var(--bg-secondary);
        }

        .programs-grid {
            display: grid;
            grid-template-columns: 1fr;
            gap: 24px;
        }

        @media (min-width: 640px) {
            .programs-grid {
                grid-template-columns: repeat(2, 1fr);
            }
        }

        @media (min-width: 1024px) {
            .programs-grid {
                grid-template-columns: repeat(4, 1fr);
            }
        }

        .program-card {
            background: var(--bg-card);
            border-radius: var(--radius-sm);
            overflow: hidden;
            box-shadow: var(--shadow-subtle);
            transition: box-shadow var(--transition), transform var(--transition);
        }

        .program-card:hover {
            box-shadow: var(--shadow-elevated);
            transform: translateY(-4px);
