            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        .program-content {
            padding: 20px;
        }

        .program-title {
            font-size: 16px;
            font-weight: 600;
            line-height: 1.4;
        }

        /* Latest Videos */
        .latest-videos {
            padding: 80px 0;
